Read text file `api/flow/startupRecovery.js`.
1|// Domain: The Flow — startup recovery after a stop, crash, or restart.
2|import {
3|	autoResumeTask,
4|	freshSchedulerStats,
5|	isAutoResumableWithReason,
6|	kickScheduler,
7|	reconcileInterruptedRuns,
8|	resolveCandidateStage,
9|	resolveStagesForTask,
10|	startScheduler,
11|} from "./taskScheduler.js";
12|import { runInterruptionReconcilePlugins } from "./stageLifecycle.js";
13|import { isCircuitEnabled, isTripped, loadCircuitState } from "./circuitBreaker.js";
14|
15|/***
16| * MARK: startupRecoverySummary
17| * @description One-line human summary of a startup recovery pass, logged at
18| *   boot so an operator can see what the restart picked up.
19| * @param {Object} summary
20| * @returns {string}
21| * @example startupRecoverySummary({ interruptedFound: 2, autoResumed: 1 }) => "startup recovery: ..."
22| ***/
23|export function startupRecoverySummary(summary) {
24|	const found = summary?.interruptedFound ?? 0;
25|	const resumed = summary?.autoResumed?.length ?? 0;
26|	const left = Math.max(0, found - resumed);
27|	return (
28|		`startup recovery: ${found} interrupted → ${resumed} auto-resumed, ` +
29|		`${left} left for operator`
30|	);
31|}
32|
33|/***
34| * MARK: autoResumeInterrupted
35| * @description Converts every auto-resumable `interrupted` task back to
36| *   `in_stage` (via `autoResumeTask`, mirroring manual resume) without
37| *   dispatching anything itself. Merge interruptions with rehydration
38| *   markers resume here when the continuity plugins left them unfinished
39| *   (no fresh result); markerless ones stay parked with a recorded reason.
40| *   While the circuit breaker is tripped nothing flips
41| *   (the deferral reason is recorded instead). Idempotent: a second pass
42| *   finds nothing to convert.
43| * @param {Object} store
44| * @returns {Array<Object>} `{ projectId, taskId }` pairs that were resumed.
45| ***/
46|export function autoResumeInterrupted(store) {
47|	if (
48|		!store.projectStore ||
49|		typeof store.projectStore.listProjects !== "function"
50|	) {
51|		return [];
52|	}
53|	const resumed = [];
54|	// WP6 tripped-engine exclusion (WP1 respect): while the circuit breaker
55|	// is tripped, flipping tasks is pointless (dispatch is gated) and noisy.
56|	// Record the deferral reason on each parked task and resume nothing.
57|	const tripped = isCircuitEnabled() && isTripped(store);
58|	for (const project of store.projectStore.listProjects()) {
59|		let tasks;
60|		try {
61|			tasks = store.listTasks(project.id, project.cwd);
62|		} catch {
63|			continue;
64|		}
65|		for (const task of tasks) {
66|			if (task?.status !== "interrupted") continue;
67|			// Fail-safe: one unreadable task must never block the rest of the
68|			// pass — or boot, when called from performStartupRecovery.
69|			try {
70|				// Same id-then-name resolution as the scheduler candidate
71|				// scan so startup and ticks agree on which stage a task sits
