481| * @returns {Array<Object>} One display row per stage, each carrying `tryCount` when its group had more than one row.
482| ***/
483|export function summarizeStageRuns(entries = [], stages = []) {
484|  const list = Array.isArray(entries) ? entries : [];
485|  const groups = new Map();
486|  const order = [];
487|  for (const entry of list) {
488|    const label = resolveTimelineStageLabel(entry?.stage, stages);
489|    if (!label) {
490|      // No stage label: never grouped, always kept as its own row.
491|      order.push({ label: null, entry });
492|      continue;
493|    }
494|    // Stage-name matching is case-insensitive everywhere else (the backend
495|    // matches names case-insensitively), so grouping is too: 'Design' and
496|    // 'design' are one stage, rendered under the first-seen spelling.
497|    const groupKey = label.toLowerCase();
498|    if (!groups.has(groupKey)) {
499|      groups.set(groupKey, { label, rows: [] });
500|      order.push({ label: groupKey, entry: null });
501|    }
502|    groups.get(groupKey).rows.push(entry);
503|  }
504|  const result = [];
505|  for (const slot of order) {
506|    if (slot.label === null) {
507|      // A copy, like every other display row: rendering must never be able
508|      // to mutate the stored timeline through this array.
509|      result.push({ ...slot.entry });
510|      continue;
511|    }
512|    const { label: displayLabel, rows: group } = groups.get(slot.label);
513|    // Representative: the chronologically latest row of the group (latest
514|    // status/reason/attribution); ties and unparseable timestamps fall back
515|    // to the first row encountered.
516|    let latest = null;
517|    let latestMs = -Infinity;
518|    for (const candidate of group) {
519|      const raw = Date.parse(candidate?.timestamp);
520|      const ms = Number.isNaN(raw) ? -Infinity : raw;
521|      // Strictly greater only: on ties (or unparseable timestamps) the first
522|      // row encountered wins — in newest-first display order that IS the
523|      // latest row.
524|      if (latest === null || ms > latestMs) {
525|        latest = candidate;
526|        latestMs = ms;
527|      }
528|    }
529|    const row = { ...latest, stage: displayLabel };
530|    if (group.length > 1) {
531|      row.tryCount = Math.min(group.length, STAGE_RUN_TRY_COUNT_CAP);
532|    }
533|    result.push(row);
534|  }
535|  return result;
