test("interrupts: drops the lease and parks the task", () => {
	const { executionId } = claimed(ctx);
	const out = ledger.interruptExecution({
		claimStore: ctx.claimStore,
		taskStore: ctx.taskStore,
		projectId: "p1",
		taskId: "t1",
		runnerId: "r1",
		executionId,
