47|import { execFileSync } from "node:child_process";
48|import fs from "node:fs";
49|import os from "node:os";
50|import path from "node:path";
51|import { prepareWorkdir, WORKTREE_CAP, WORKTREE_EVICT_STALE_MS } from "./project.js";
52|
53|function localRepo() {
54|  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "kb-cap-src-"));
55|  const git = (args) => execFileSync("git", args, { cwd: dir, stdio: "ignore" });
56|  git(["init", "-q"]); git(["config", "user.email", "t@t.t"]); git(["config", "user.name", "t"]);
57|  fs.writeFileSync(path.join(dir, "f.txt"), "x");
58|  git(["add", "."]); git(["commit", "-qm", "init"]);
59|  return dir;
60|}
61|
62|describe("WORKTREE_CAP_REACHED (Cause 1)", () => {
63|  let workRoot, src;
64|  beforeEach(() => {
65|    workRoot = fs.mkdtempSync(path.join(os.tmpdir(), "kb-cap-root-"));
66|    src = localRepo();
67|    // Fill the cap with FRESH orphans (mtime now -> nothing stale to evict)
68|    for (let i = 0; i < WORKTREE_CAP; i++) {
