73|
74|  it("refuses with WORKTREE_CAP_REACHED when all orphans are fresh", async () => {
75|    await assert.rejects(
76|      prepareWorkdir({ localPath: src, workRoot, taskId: "newtask" }),
77|      (err) => {
78|        assert.equal(err.code, "WORKTREE_CAP_REACHED");
79|        assert.match(err.message, /Worktree cap reached \(~5\)/);
80|        assert.match(err.message, /nothing stale to evict/);
81|        return true;
82|      },
83|    );
84|  });
85|
86|  it("evicts the stalest orphan instead of refusing once one is old", async () => {
87|    const staleDir = path.join(workRoot, "kb-orphan0");
88|    const old = new Date(Date.now() - WORKTREE_EVICT_STALE_MS - 60_000);
89|    fs.utimesSync(staleDir, old, old);
90|    const out = await prepareWorkdir({ localPath: src, workRoot, taskId: "newtask" });
91|    assert.equal(out.evicted, "kb-orphan0");
92|    assert.ok(out.workdir.endsWith("kb-newtask"));
93|  });
94|});
95|```
