113|import { isAutoResumableWithReason } from "./scheduler/isAutoResumableWithReason.js";
114|// ... mock claimStore/taskStore exactly like executionLedger.test.js ...
115|
116|test("five cap refusals on one stage escalate and then park as runner-death-loop", () => {
