122|    const { executionId } = claimed(ctx); // re-claim after each dropped lease
123|    out = ledger.interruptExecution({ claimStore: ctx.claimStore, taskStore: ctx.taskStore,
124|      projectId: "p1", taskId: "t1", runnerId: "r1", executionId, reason: CAP_REASON });
125|  }
